#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn concat(a: &Vec<u64>, b: &Vec<u64>) -> (res: Vec<u64>)
    requires
        a.len() <= 100,
        b.len() <= 100,
    ensures
        res.len() == a.len() + b.len(),
        forall|i: int| 0 <= i < a.len() ==> res[i] == a[i],
        forall|i: int| a.len() <= i < res.len() ==> res[i] == b[i - a.len()],
{
    let mut res: Vec<u64> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            0 <= i <= a.len(),
            res.len() == i,
            forall|k: int| 0 <= k < i ==> res[k] == a[k],
        decreases a.len() - i
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            0 <= j <= b.len(),
            res.len() == a.len() + j,
            forall|k: int| 0 <= k < a.len() ==> res[k] == a[k],
            forall|k: int| 0 <= k < j ==> res[a.len() + k] == b[k],
        decreases b.len() - j
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!